SELECT s.id, s.student_id AS studentId, st.student_name AS studentName, st.student_no AS studentNo, s.course_id AS courseId, c.course_no AS courseNo, c.name AS courseName, c.credit, c.hours, c.semester, c.study_nature AS studyNature, t.teacher_name AS teacherName, s.score, s.usual_score AS usualScore, s.exam_score AS examScore, s.total_score AS totalScore, s.usual_weight AS usualWeight, s.exam_weight AS examWeight, s.grade, s.comment, s.teacher_id AS teacherId, DATE_FORMAT(s.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime FROM score s LEFT JOIN course c ON s.course_id = c.id LEFT JOIN student st ON s.student_id = st.id LEFT JOIN teacher t ON s.teacher_id = t.id
AND s.student_id = #{studentId}
AND s.course_id = #{courseId}
AND s.grade = #{grade}
AND c.semester = #{semester}
AND s.teacher_id = #{teacherId}
ORDER BY c.semester DESC, s.update_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM score s
LEFT JOIN course c ON s.course_id = c.id


        AND s.student_id = #{studentId}


        AND s.course_id = #{courseId}


        AND s.grade = #{grade}


        AND c.semester = #{semester}


        AND s.teacher_id = #{teacherId}

SELECT sc.id AS scoreId, st.id AS studentId, st.student_no AS studentNo, st.student_name AS studentName, cs.course_id AS courseId, c.name AS courseName, sc.usual_score AS usualScore, sc.exam_score AS examScore, sc.total_score AS totalScore, sc.usual_weight AS usualWeight, sc.exam_weight AS examWeight, sc.grade, sc.comment, sc.teacher_id AS teacherId, DATE_FORMAT(sc.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime, CASE WHEN te.id IS NOT NULL THEN true ELSE false END AS evaluated FROM course_selection cs INNER JOIN student st ON cs.student_id = st.id INNER JOIN course c ON cs.course_id = c.id LEFT JOIN score sc ON sc.student_id = st.id AND sc.course_id = cs.course_id LEFT JOIN teaching_evaluation te ON te.student_id = st.id AND te.course_id = cs.course_id
cs.status = 1
AND cs.course_id = #{courseId}
AND (st.student_no LIKE CONCAT('%', #{keyword}, '%') OR st.student_name LIKE CONCAT('%', #{keyword}, '%'))
AND sc.grade = #{grade}
ORDER BY st.student_no ASC

SELECT COUNT(*) FROM course_selection cs INNER JOIN student st ON cs.student_id = st.id
cs.status = 1
AND cs.course_id = #{courseId}
